<?php require 'config.php'; $id=(int)($_GET['id']??0); $st=$conn->prepare('SELECT * FROM students WHERE id=?');$st->bind_param('i',$id);$st->execute();$student=$st->get_result()->fetch_assoc(); if(!$student) die('Student not found.'); $st=$conn->prepare('SELECT * FROM student_files WHERE student_id=? ORDER BY upload_date DESC');$st->bind_param('i',$id);$st->execute();$files=$st->get_result(); ?>
<!doctype html><html><head><meta charset="utf-8"><title>Student Profile</title><link rel="stylesheet" href="style.css"></head><body><div class="wrap"><h1><?=htmlspecialchars($student['name'])?></h1><div class="profile"><p><b>Roll:</b> <?=htmlspecialchars($student['roll_number'])?></p><p><b>Email:</b> <?=htmlspecialchars($student['email'])?></p><p><b>Course:</b> <?=htmlspecialchars($student['course'])?></p></div><h2>Uploaded Files</h2><?php if(!$files->num_rows): ?><p>No files uploaded.</p><?php else: while($f=$files->fetch_assoc()): ?><div class="file"><a href="<?=htmlspecialchars($f['file_path'])?>" target="_blank"><?=htmlspecialchars($f['original_name'])?></a><small><?=htmlspecialchars($f['file_type'])?> · <?=htmlspecialchars($f['upload_date'])?></small></div><?php endwhile; endif; ?><p><a class="btn" href="form.php?id=<?=$id?>">Edit</a> <a href="index.php">Back</a></p></div></body></html>
